#include "rate_limiter.h"
#include "../token/token.h"
#include <iostream>

namespace middleware {

RateLimiter::RateLimiter(gw::Token& token) : token_(token) {}

bool RateLimiter::allow(const std::string& token_str) {
    if (!token_.validate(token_str)) {
        std::cerr << "rate: invalid token\n";
        return false;
    }
    std::cout << "rate: allowed\n";
    return true;
}

} // namespace middleware

#include "cors_middleware.h"
#include "../token/token.h"
#include <iostream>

namespace middleware {

CorsMiddleware::CorsMiddleware(gw::Token& token) : token_(token) {}

bool CorsMiddleware::preflight(const std::string& token_str) {
    if (!token_.validate(token_str)) {
        std::cerr << "cors: invalid token\n";
        return false;
    }
    std::cout << "cors: preflight ok\n";
    return true;
}

} // namespace middleware

#include "auth_middleware.h"
#include "../token/token.h"
#include <iostream>

namespace middleware {

AuthMiddleware::AuthMiddleware(gw::Token& token) : token_(token) {}

bool AuthMiddleware::check(const std::string& token_str) {
    if (!token_.validate(token_str)) {
        std::cerr << "auth: rejected\n";
        return false;
    }
    return true;
}

} // namespace middleware

#include "api_handler.h"
#include "../token/token.h"
#include "../gateway/router.h"
#include <iostream>

namespace handlers {

ApiHandler::ApiHandler(gw::Token& token, gw::Router& router)
    : token_(token), router_(router) {}

bool ApiHandler::handle(const gw::Request& req) {
    std::string tok = req.headers.count("Authorization")
        ? req.headers.at("Authorization")
        : "";
    if (!token_.validate(tok)) {
        std::cerr << "api: unauthorized\n";
        return false;
    }
    std::string target = router_.route(req);
    std::cout << "api: routed to " << target << "\n";
    return true;
}

} // namespace handlers
